use gpui::{div, px, IntoElement, ParentElement, Styled};

pub fn settings_window(pages: Vec<&'static str>, current: usize) -> impl IntoElement {
    div()
        .flex()
        .child(div().w(px(200.0)).children(pages.iter().map(|page| div().h(px(28.0)).child(*page))))
        .child(div().flex_1().child(pages[current]))
}
